<script lang="ts">
 import {onMount,onDestroy,tick,untrack} from 'svelte';
 import {surface} from './surfaces';
 import {SyncSession,type SyncStatus} from '../sync/session';
 import {parseInvitation} from '../sync/crypto';
 import {canonical,key,type SyncRecord} from '../sync/records';
 import type {Core} from '../core/core';
 import type {SQLiteAdapter} from '../storage/adapter';
 import type QrScanner from 'qr-scanner';
 let {core,onclose,invitation='',workspaceName='Основное'}:{core:Core;onclose:()=>void;invitation?:string;workspaceName?:string}=$props();
 let syncStatus=$state<SyncStatus>({phase:'idle',message:'',devices:[],conflicts:0}),mode=$state<'home'|'qr'|'scan'|'link'>('home'),qr=$state(''),link=$state(''),name=$state(''),error=$state(''),feedback=$state(''),busy=$state(false),differences=$state<SyncRecord[]>([]),selected=$state('');
 let video=$state<HTMLVideoElement>();let showLink=$state(false);let scanner:QrScanner|undefined,alive=true,qrValue='';
 const storage=untrack(()=>core.storage as SQLiteAdapter);
 const session=new SyncSession(untrack(()=>core),value=>{syncStatus=value;if(value.invite)void makeQr(value.invite).catch(()=>error='Не удалось показать QR. Используйте ссылку подключения.');if(value.phase==='done')void refresh().catch(e=>error=e.message);});
 const connected=$derived(['verify','waiting','syncing','done','connecting'].includes(syncStatus.phase));
 async function makeQr(value:string){if(qrValue===value)return;qrValue=value;const QR=await import('qrcode');const result=await QR.toDataURL(value,{width:600,margin:4,errorCorrectionLevel:'M',color:{dark:'#141618',light:'#ffffff'}});if(alive)qr=result;}
 async function refresh(){differences=await storage.syncConflicts();}
 async function run(action:()=>Promise<unknown>){busy=true;error='';try{await action();}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function connect(){const invite=parseInvitation(link.trim());stopCamera();await session.setName(name);await session.connect(invite);}
 async function copyLink(){try{await navigator.clipboard.writeText(syncStatus.invite!);feedback='Ссылка скопирована. Откройте её на своём втором устройстве.';}catch{showLink=true;feedback='Выделите и скопируйте ссылку ниже.';}}
 function stopCamera(){scanner?.destroy();scanner=undefined;}
 async function scan(){mode='scan';await tick();try{const {default:Qr}=await import('qr-scanner');if(!alive||mode!=='scan')return;scanner=new Qr(video!,result=>{link=result.data;stopCamera();mode='link';},{preferredCamera:'environment',maxScansPerSecond:8,highlightScanRegion:true});await scanner.start();}catch{stopCamera();error='Не удалось открыть камеру. Разрешите доступ в браузере, выберите изображение QR или вставьте ссылку.';mode='link';}}
 async function scanFile(file?:File){if(!file)return;const {default:Qr}=await import('qr-scanner');const result=await Qr.scanImage(file,{returnDetailedScanResult:true});parseInvitation(result.data);link=result.data;mode='link';}
 async function resolve(r:SyncRecord,choice:string){await storage.syncResolve(key(r),canonical(r),choice);await core.refresh();await session.refreshConflicts();await refresh();selected='';feedback='Версия сохранена. Синхронизируйте ещё раз, чтобы передать выбор.';}
 function describeVersion(v:any){return [({normal:'Обычные',now:'Сейчас',archived:'Архив',paused:'Пауза'} as Record<string,string>)[v.state],v.pinned?'Закреплена':'',`Важность: ${v.importance+1}`].filter(Boolean).join(' · ');}
 function linkTitle(v:any){const name=(id:string)=>core.data.atoms.find(a=>a.id===id)?.title||'Удалённая заметка';return `${name(v.from)} → ${name(v.to)}`;}
 onMount(()=>{void storage.getSetting<string>('sync:device-name').then(value=>name=value||(/Android|iPhone|iPad/.test(navigator.userAgent)?'Телефон':'Компьютер'));if(invitation){mode='link';link=invitation;}void session.start();void refresh();});
 onDestroy(()=>{alive=false;stopCamera();session.destroy();});
</script>
<div class="scrim" use:surface={{close:onclose}}><div class="editor settings device-sync" role="dialog" aria-modal="true" aria-label="Устройства и синхронизация" tabindex="-1">
 <div class="row"><h2>Ваши устройства</h2><button aria-label="Закрыть синхронизацию" onclick={onclose}><svg viewBox="0 0 24 24"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div>
 <p class="sync-intro">Одна карта — на телефоне и компьютере. Оба устройства равноправны. Заметки передаются между ними, без облачного хранилища.</p>
 <p class="sync-help">Текущее хранилище: <strong>{workspaceName}</strong></p>
 {#if error}<p role="alert" class="inline-error">{error}</p>{/if}
 {#if feedback}<p role="status" class="sync-feedback">{feedback}</p>{/if}
 {#if !connected}
  <label class="device-name">Это устройство<input aria-label="Название устройства" maxlength="80" bind:value={name} onblur={()=>run(()=>session.setName(name))}/></label>
  {#if mode==='home'}
   <div class="sync-choices"><button disabled={syncStatus.phase!=='ready'} onclick={()=>mode='qr'}><svg viewBox="0 0 24 24"><path d="M3 3h6v6H3zM15 3h6v6h-6zM3 15h6v6H3zM15 15h2v2h-2zM20 14v4h-2v3h3M13 21v-3M13 12h8M3 12h7"/></svg><span>Показать QR<small>Сканируйте другим устройством</small></span></button><button disabled={syncStatus.phase!=='ready'} onclick={()=>run(scan)}><svg viewBox="0 0 24 24"><path d="M3 8V3h5M16 3h5v5M21 16v5h-5M8 21H3v-5M4 12h16"/></svg><span>Сканировать QR<small>Камера этого устройства</small></span></button></div>
   <button class="sync-text" onclick={()=>mode='link'}>Подключиться по ссылке</button>
  {:else if mode==='qr'}
   <div class="qr-card">{#if qr}<img src={qr} alt="QR для подключения своего устройства" width="250" height="250"/>{/if}<p>На втором устройстве откройте камеру<br/>или Phosphorea → Устройства → Сканировать QR.</p><small>Код действует 10 минут. Не публикуйте его.</small></div>
   <div class="sync-secondary"><button onclick={()=>run(copyLink)}>Скопировать ссылку</button><button onclick={()=>run(async()=>{qr='';showLink=false;await session.reset();})}>Новый QR</button></div>
   {#if showLink}<textarea aria-label="Ссылка для другого устройства" readonly rows="3" value={syncStatus.invite} onclick={e=>e.currentTarget.select()}></textarea>{/if}
  {:else if mode==='scan'}
   <div class="scan-frame"><video bind:this={video} autoplay playsinline muted aria-label="Камера для QR"></video></div><p class="sync-help">Наведите камеру на QR другого вашего устройства.</p>
  {:else}
   <label class="invite-input">Ссылка подключения<textarea aria-label="Ссылка подключения" rows="3" bind:value={link} placeholder="Вставьте ссылку с другого устройства" autocomplete="off" spellcheck="false"></textarea></label><button class="sync-primary" disabled={busy||syncStatus.phase!=='ready'||!link.trim()} onclick={()=>run(connect)}>Подключиться</button>
   <label class="sync-file">Выбрать изображение QR<input type="file" accept="image/*" onchange={e=>run(()=>scanFile(e.currentTarget.files?.[0]))}/></label>
  {/if}
  {#if mode!=='home'}<button class="sync-text" onclick={()=>{stopCamera();mode='home';error='';}}>Назад</button>{/if}
 {:else}
  <div class="peer-label"><svg viewBox="0 0 24 24"><path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6ZM8 12l3 3 5-6"/></svg><span>{syncStatus.remoteName||'Другое ваше устройство'}</span></div>
  {#if syncStatus.phase==='verify'||syncStatus.phase==='waiting'}
   <h3>Одинаковые эмодзи?</h3><p class="sync-help">Сравните все шесть знаков на двух экранах в этом порядке. Подтвердите только своё устройство.</p><div class="verification-code" aria-label="Код проверки">{#each syncStatus.emojis||[] as emoji}<span>{emoji}</span>{/each}</div>
   {#if syncStatus.phase==='verify'}<button class="sync-primary" disabled={busy} onclick={()=>run(()=>session.confirm())}>Да, совпадают</button><button class="sync-text" onclick={()=>run(()=>session.reset())}>Не совпадают — отменить</button>{:else}<p class="sync-help" role="status">{syncStatus.message}</p>{/if}
  {:else if syncStatus.phase==='done'}
   <h3>{syncStatus.conflicts?'Есть разные версии':'Карты синхронизированы'}</h3><p role="status">{syncStatus.message}</p><button class="sync-primary" disabled={busy} onclick={()=>run(()=>session.sync())}>Синхронизировать ещё раз</button><p class="sync-help">Продолжайте на любом устройстве. Для следующего обмена откройте это окно на обоих; повторно сверять эмодзи не нужно.</p>
  {:else}<p class="sync-help" role="status">{syncStatus.message}</p>{#if syncStatus.phase==='syncing'}<progress aria-label="Передача карты" max="100" value={syncStatus.progress||0}></progress>{/if}{/if}
 {/if}
 {#if syncStatus.phase==='starting'||syncStatus.phase==='error'}<p class="sync-help" role="status">{syncStatus.message}</p>{/if}
 {#if syncStatus.phase==='error'}<button onclick={()=>run(()=>session.reset())}>Попробовать снова</button>{/if}
 {#if differences.length}<section class="sync-differences"><h3>Разные версии · {differences.length}</h3><p class="sync-help">Обе версии уже сохранены. Удаление на одном устройстве тоже не стирает независимую правку на другом.</p>
  {#each differences as r (key(r))}<div class="sync-difference"><button class="difference-title" aria-expanded={selected===key(r)} onclick={()=>selected=selected===key(r)?'':key(r)}>{r.kind==='atom'?String((r.heads.find(h=>h.value)?.value as any)?.title||'Удалённая заметка'):r.kind==='link'?'Связь между заметками':'Типы заметок'}<span>{r.heads.length} версии</span></button>
   {#if selected===key(r)}{#each r.heads as h}<article class="version-choice"><small>{h.device} · {new Date(h.at).toLocaleString('ru-RU')}</small>{#if h.value===null}<strong>Удалено на этом устройстве</strong>{:else if r.kind==='atom'}<strong>{(h.value as any).title}</strong><p class="sync-help">{describeVersion(h.value)}</p><pre>{(h.value as any).content||'Без текста'}</pre><details><summary>Оформление и другие свойства</summary><pre>{JSON.stringify({type:(h.value as any).type,appearance:(h.value as any).appearance,aliases:(h.value as any).aliases,properties:(h.value as any).properties,x:(h.value as any).x,y:(h.value as any).y},null,2)}</pre></details>{:else if r.kind==='link'}<strong>{linkTitle(h.value)}</strong>{:else}<pre>{JSON.stringify(h.value,null,2)}</pre>{/if}<button disabled={busy} onclick={()=>run(()=>resolve(r,h.id))}>{h.value===null?'Подтвердить удаление':'Оставить эту версию'}</button></article>{/each}{#if r.kind==='atom'}<button class="sync-primary" disabled={busy} onclick={()=>run(()=>resolve(r,'both'))}>Сохранить обе отдельными заметками</button>{/if}{/if}
  </div>{/each}</section>{/if}
 {#if syncStatus.devices.length&&!connected}<section class="trusted-devices"><h3>Уже знакомы</h3>{#each syncStatus.devices as device}<div><button disabled={syncStatus.phase!=='ready'} onclick={()=>run(async()=>{await session.setName(name);session.reconnect(device);})}><svg viewBox="0 0 24 24"><path d="M4 4h16v12H4zM8 20h8M12 16v4"/></svg><span>{device.name||'Устройство'}<small>{device.lastSync?`Обмен: ${new Date(device.lastSync).toLocaleDateString('ru-RU')}`:'Подтверждено'}</small></span></button><button class="forget-device" aria-label={`Забыть ${device.name}`} onclick={()=>run(()=>session.forget(device.id))}><svg viewBox="0 0 24 24"><path d="m8 8 8 8M16 8l-8 8"/></svg></button></div>{/each}</section>{/if}
 <details class="sync-privacy"><summary>Как это работает и что защищено</summary><p>QR содержит одноразовый секрет и отпечаток ключа. Заметки не передаются до проверки ключей и подтверждения с двух сторон. Соединение дополнительно шифруется; известное устройство узнаётся по сохранённому ключу.</p><p>Для нахождения устройств нужен интернет и служебный сервер PeerJS. Заметки на нём не хранятся. В некоторых сетях прямое соединение блокируется — попробуйте другую сеть. Держите оба окна открытыми до окончания обмена.</p><p>Синхронизируются заметки, связи, папки, задачи, оформление атомов и типы заметок текущего хранилища. Настройки приложения, плагины и внешние файлы Obsidian не переносятся. Это не шифрование базы на телефоне и не защита от вредоносного обновления приложения.</p></details>
</div></div>
<style>
 .device-sync{width:460px;gap:16px}.device-sync h2{margin:0}.device-sync h3{font-size:18px;font-weight:550;margin:10px 0}.device-sync p{margin:0}.sync-intro,.sync-help,.sync-privacy p{font-size:13px;line-height:1.6;color:var(--theme-muted)}.device-name{display:grid;gap:7px;font-size:12px}.device-name input{width:100%;background:var(--theme-surfaceAlt);border-color:transparent}.sync-choices{display:grid;gap:8px}.sync-choices button,.trusted-devices>div>button:first-child{display:flex;align-items:center;gap:14px;text-align:left;background:var(--theme-surfaceAlt);border:0;padding:16px}.sync-choices span,.trusted-devices span{display:grid;gap:4px;font-size:14px}.sync-choices small,.trusted-devices small{font-size:11px;color:var(--theme-muted)}svg{width:22px;height:22px;flex:none;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}.sync-text{background:transparent;border:0;color:var(--theme-muted);font-size:12px}.sync-primary{width:100%;background:var(--theme-text);color:var(--theme-surface);border:0;min-height:48px}.qr-card{display:grid;justify-items:center;gap:14px;text-align:center}.qr-card img{width:min(250px,100%);height:auto;border-radius:18px;background:#fff}.qr-card p{font-size:12px;line-height:1.55}.qr-card small{font-size:10px;color:var(--theme-muted)}.sync-secondary{display:flex;justify-content:center;gap:8px}.sync-secondary button{font-size:12px;flex:1;padding:10px}.scan-frame{border-radius:20px;overflow:hidden;background:var(--theme-background);aspect-ratio:1}.scan-frame video{display:block;width:100%;height:100%;object-fit:cover}.invite-input{display:grid;gap:8px}.invite-input textarea{width:100%;font-size:12px;resize:vertical;overflow-wrap:anywhere}.sync-file{position:relative;display:flex;justify-content:center;min-height:44px;align-items:center;font-size:12px;color:var(--theme-muted);overflow:hidden}.sync-file input{position:absolute;inset:0;opacity:0;width:100%;cursor:pointer}.peer-label{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--theme-muted)}.verification-code{display:grid;grid-template-columns:repeat(6,1fr);gap:4px;padding:18px 0}.verification-code span{display:grid;place-items:center;min-height:48px;border-radius:12px;background:var(--theme-surfaceAlt);font-size:27px}.sync-feedback{font-size:12px;color:var(--theme-accent)}progress{width:100%;height:5px;accent-color:var(--theme-text)}.sync-differences{display:grid;gap:10px}.sync-difference{border-radius:16px;background:var(--theme-surfaceAlt);padding:8px}.difference-title{width:100%;border:0;background:transparent;display:flex;justify-content:space-between;align-items:center;gap:10px;font-size:13px;text-align:left;overflow-wrap:anywhere}.difference-title span{font-size:10px;color:var(--theme-muted);white-space:nowrap}.version-choice{display:grid;gap:10px;padding:12px}.version-choice small{font-size:10px;color:var(--theme-muted)}.version-choice strong{font-size:14px;overflow-wrap:anywhere}.version-choice pre{max-height:200px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font-family:inherit;font-size:12px;line-height:1.6;margin:0}.version-choice button{font-size:12px}.trusted-devices>div{display:flex;gap:6px;margin-top:8px}.trusted-devices>div>button:first-child{flex:1;min-width:0}.trusted-devices .forget-device{border:0;background:transparent;padding:10px}.sync-privacy{font-size:12px;color:var(--theme-muted);margin-top:8px}.sync-privacy summary{cursor:pointer;padding:10px 0}.sync-privacy p{font-size:12px;margin:8px 0}
</style>
